"use client";

import React, { useState, useRef } from "react";
import { useDictionary } from "@/hooks/useDictionary";
import Header from "@/components/Header";
import SearchFilters from "@/components/SearchFilters";
import WordCard from "@/components/WordCard";
import WordDrawer from "@/components/WordDrawer";
import AkilliKlavye from "@/components/AkilliKlavye";
import { GruplanmisKelime } from "@/types/dictionary";

export default function Home() {
  const dictionary = useDictionary();
  const [mod, setMod] = useState("baslayan");
  const [hedefDil, setHedefDil] = useState("tumu");
  const [karanlikMod, setKaranlikMod] = useState(false);
  const [metinBoyutu, setMetinBoyutu] = useState(16);
  const [seciliKelimeGrubu, setSeciliKelimeGrubu] = useState<GruplanmisKelime | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  if (dictionary.loading) {
    return <div className="loading-screen">📖 Sözlük veritabanı yükleniyor...</div>;
  }

  return (
    <main style={{ maxWidth: "840px", margin: "0 auto", padding: "24px 16px" }}>
      <Header 
        metinBoyutu={metinBoyutu} 
        setMetinBoyutu={setMetinBoyutu} 
        karanlikMod={karanlikMod} 
        setKaranlikMod={setKaranlikMod} 
      />

      <SearchFilters 
        dictionary={dictionary} 
        hedefDil={hedefDil} 
        setHedefDil={setHedefDil} 
        mod={mod} 
        setMod={setMod} 
        inputRef={inputRef} 
      />

      <AkilliKlavye 
        inputRef={inputRef} 
        sorgu={dictionary.searchQuery} 
        setSorgu={dictionary.setSearchQuery} 
      />

      <section className="results-list">
        {dictionary.filtrelenmisSonuclar.map((grup, idx) => (
          <WordCard 
            key={idx} 
            grup={grup} 
            onSelect={() => setSeciliKelimeGrubu(grup)} 
          />
        ))}
      </section>

      {seciliKelimeGrubu && (
        <WordDrawer 
          grup={seciliKelimeGrubu} 
          onClose={() => setSeciliKelimeGrubu(null)} 
        />
      )}
    </main>
  );
}